    message.rpc = object.rpc ?? "";
    message.fullyQualifiedMethod = object.fullyQualifiedMethod ?? "";
    message.effect = object.effect ?? 0;
    message.replaySafety = object.replaySafety ?? 0;
    message.executionScope = object.executionScope ?? 0;
